    """
    Implements a backtracking algorithm for regex matching supporting:
    - Literal characters
    - '.' (matches any single character)
    - '*' (matches zero or more of the preceding element)
    - '+' (matches one or more of the preceding element)
    """

    def is_match(p_index: int, t_index: int) -> bool:
