                if (p_index + 1 < len(pattern) and pattern[p_index + 1] in '*+'):
                    if pattern[p_index + 1] == '*':
                        # Match zero or more
                        return (is_match(p_index, t_index + 1) or
                                is_match(p_index + 2, t_index))
                    elif pattern[p_index + 1] == '+':
                        # Match one or more
                        return (is_match(p_index, t_index + 1) or
                                is_match(p_index + 2, t_index) or
                                is_match(p_index, t_index + 1))
                else:
                    return is_match(p_index + 1, t_index + 1)

            if p_index + 1 < len(pattern) and pattern[p_index + 1] == '*':
