                        is_match(p_index, t_index + 1))

            if p_index + 1 < len(pattern) and pattern[p_index + 1] == '+':
                # Handle '+'
                return (is_match(p_index + 2, t_index) or
                        is_match(p_index, t_index + 1))

        return False

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements a regex matching algorithm using recursion and memoization to support
    literal characters, '.', '*', and '+' operators.
    """

    def is_match(i: int, j: int, memo: dict) -> bool:
        if (i, j) in memo:
            return memo[(i, j)]

        if j == len(pattern):
            result = i == len(text)
        else:
            first_match = i < len(text) and (pattern[j] == text[i] or pattern[j] == '.')

            if j + 1 < len(pattern) and pattern[j + 1] in '*+':
                if pattern[j + 1] == '*':
                    result = (is_match(i, j + 2, memo) or 
                               (first_match and is_match(i + 1, j, memo)))
                else:  # pattern[j + 1] == '+'
                    result = first_match and (is_match(i + 1, j, memo) or 
                                              is_match(i + 1, j + 2, memo))
            else:
                result = first_match and is_match(i + 1, j + 1, memo)

        memo[(i, j)] = result
        return result

    return is_match(0, 0, {})
